#include <iostream>
using namespace std;

struct QNode {
    int iData;
    QNode* next;
};

class L_Queue {
private:
    QNode* front;
    QNode* back;
public:
    L_Queue() {
        front = NULL;
        back = NULL;
    }
    bool isEmpty() {
        return front == NULL;
    }
    void enqueue(int value) {
        QNode* newNode = new QNode();
        newNode->iData = value;
        newNode->next = NULL;
        if (back == NULL) {
            front = newNode;
            back = newNode;
        } else {
            back->next = newNode;
            back = newNode;
        }
        cout << value << " joins the queue" << endl;
    }
    void dequeue() {
        if (isEmpty()) {
            cout << "The queue is empty" << endl;
            return;
        }
        QNode* temp = front;
        front = front->next;
        cout << temp->iData << " leaves the queue" << endl;
        delete temp;
        if (front == NULL) {
            back = NULL;
        }
    }
};

int main() {
    L_Queue q;
    q.enqueue(10);
    q.enqueue(20);
    q.dequeue();
    q.dequeue();
    q.enqueue(30);
    q.dequeue();
    return 0;
}
